#!/usr/bin/env python3
"""Validate /results/dns-decode against every stated formatting requirement."""
import json
import os

D = "/results/dns-decode"
IDS = [f"m{i}" for i in range(1, 11)]
KEYS = ["id", "offset", "name", "truncated", "infinite_loop", "label_limit", "ok"]
errs = []

names = sorted(os.listdir(D))
expected = sorted([f"{i}.json" for i in IDS] + ["manifest.csv"])
if names != expected:
    errs.append(f"dir contents: {names} != {expected}")
print(f"file count: {len(names)} (expect 11) -> {'OK' if len(names) == 11 else 'FAIL'}")

manifest_rows = {}
for mid in IDS:
    p = os.path.join(D, f"{mid}.json")
    raw = open(p, "rb").read()
    if not raw.endswith(b"\n"):
        errs.append(f"{mid}: missing trailing newline")
    if raw.count(b"\n") != 1:
        errs.append(f"{mid}: expected exactly 1 newline, got {raw.count(chr(10).encode())}")
    text = raw.decode("utf-8")  # must be valid UTF-8
    body = text[:-1]
    # compact: no space after ':' or ','
    if ": " in body or ", " in body:
        errs.append(f"{mid}: not compact")
    obj = json.loads(body)
    if list(obj.keys()) != KEYS:
        errs.append(f"{mid}: key order {list(obj.keys())} != {KEYS}")
    if obj["id"] != mid or not isinstance(obj["id"], str):
        errs.append(f"{mid}: bad id")
    if not isinstance(obj["offset"], int) or isinstance(obj["offset"], bool):
        errs.append(f"{mid}: offset not int")
    for k in ("truncated", "infinite_loop", "label_limit", "ok"):
        if not isinstance(obj[k], bool):
            errs.append(f"{mid}: {k} not bool")
    if not isinstance(obj["name"], str):
        errs.append(f"{mid}: name not str")
    # hard failures: name empty, three flags false
    if not obj["ok"]:
        if obj["name"] != "" or obj["truncated"] or obj["infinite_loop"] or obj["label_limit"]:
            errs.append(f"{mid}: hard failure must have empty name and false flags")
    # round-trip: re-serialising must reproduce the bytes exactly
    if json.dumps(obj, separators=(",", ":"), ensure_ascii=False) != body:
        errs.append(f"{mid}: not canonical compact serialisation")
    manifest_rows[mid] = obj

# manifest
raw = open(os.path.join(D, "manifest.csv"), "rb").read()
if b"\r" in raw:
    errs.append("manifest: contains CR (must be LF only)")
if not raw.endswith(b"\n"):
    errs.append("manifest: missing trailing newline")
if b'"' in raw:
    errs.append("manifest: contains quotes")
lines = raw.decode("utf-8").split("\n")
if lines[-1] != "":
    errs.append("manifest: content after final newline")
lines = lines[:-1]
hdr = "id,offset,ok,truncated,infinite_loop,label_limit,name_len"
if lines[0] != hdr:
    errs.append(f"manifest header: {lines[0]!r} != {hdr!r}")
if len(lines) != 11:
    errs.append(f"manifest: {len(lines)} lines, expected 11 (header + 10)")
for i, mid in enumerate(IDS):
    o = manifest_rows[mid]
    b = lambda v: "true" if v else "false"
    want = (f"{mid},{o['offset']},{b(o['ok'])},{b(o['truncated'])},"
            f"{b(o['infinite_loop'])},{b(o['label_limit'])},"
            f"{len(o['name'].encode('utf-8'))}")
    if lines[i + 1] != want:
        errs.append(f"manifest row {mid}: {lines[i+1]!r} != {want!r}")

print("\n".join(errs) if errs else "ALL FORMAT CHECKS PASSED")
raise SystemExit(1 if errs else 0)
